-- Column types captured from production metadata only; no candidate data.
create table public.candidates(
 "id" uuid,
 "full_name" text,
 "phone" text,
 "email" text,
 "birth_date" date,
 "rnokpp" text,
 "military_rank" text,
 "military_status" text,
 "civilian_profession" text,
 "desired_position" text,
 "direction" text,
 "recruitment_status" text,
 "tcc" text,
 "vlk_status" text,
 "recruiter_id" uuid,
 "notes" text,
 "created_at" timestamp with time zone,
 "updated_at" timestamp with time zone,
 "name_gender" text,
 "name_cases" jsonb,
 "name_nominative" text,
 "name_genitive" text,
 "sex" text,
 "marital_status" text,
 "has_children" boolean,
 "worked_before" boolean,
 "served_before" boolean,
 "birth_place" text,
 "passport_data" text,
 "profile_data" jsonb,
 "military_specialty" text,
 "children_count" integer,
 "employment_status_label" text,
 "military_status_label" text,
 "responsible_recruiter_id" uuid
);
create table public.crm_archive(
 "id" uuid,
 "candidate_id" uuid,
 "full_name" text,
 "phone" text,
 "outcome" text,
 "completion_date" date,
 "destination" text,
 "reason" text,
 "incomplete" boolean,
 "order_number" text,
 "order_date" date,
 "missing_documents" text,
 "incomplete_reason" text,
 "pdf_path" text,
 "pdf_sha256" text,
 "pdf_size" bigint,
 "source_manifest" jsonb,
 "state" text,
 "error" text,
 "archived_by" uuid,
 "archived_at" timestamp with time zone
);
create table public.document_requirements(
 "id" uuid,
 "document_type" text,
 "is_required" boolean,
 "applies_to" text,
 "condition_note" text,
 "sort_order" integer,
 "active" boolean,
 "created_at" timestamp with time zone,
 "condition_field" text,
 "condition_value" text,
 "condition_behavior" text,
 "ai_enabled" boolean
);
create table public.documents(
 "id" uuid,
 "candidate_id" uuid,
 "document_type" text,
 "document_name" text,
 "storage_path" text,
 "file_name" text,
 "file_size" bigint,
 "mime_type" text,
 "uploaded_by" uuid,
 "created_at" timestamp with time zone,
 "requirement_id" uuid,
 "status" text,
 "verification_status" text,
 "verified_by" uuid,
 "verified_at" timestamp with time zone,
 "file_hash" text,
 "notes" text,
 "ai_document_type" text,
 "ai_confidence" numeric,
 "ai_candidate_name" text,
 "ai_extracted" jsonb,
 "ai_warnings" jsonb,
 "processing_status" text,
 "required" boolean,
 "template_key" text,
 "checked_at" timestamp with time zone,
 "checked_by" uuid,
 "version_group_id" uuid,
 "version_number" integer,
 "replaces_document_id" uuid,
 "ai_raw_response" jsonb,
 "ai_model" text,
 "ai_processed_at" timestamp with time zone,
 "deleted_at" timestamp with time zone,
 "deleted_by" uuid,
 "deleted_by_name" text
);
create table public.personal_files(
 "id" uuid,
 "candidate_id" uuid,
 "education" text,
 "civilian_experience" text,
 "military_experience" text,
 "family_status" text,
 "address" text,
 "autobiography" text,
 "additional_notes" text,
 "created_at" timestamp with time zone,
 "updated_at" timestamp with time zone,
 "birth_place" text,
 "passport_data" text,
 "children_info" text,
 "work_history" text,
 "military_service_history" text,
 "marriage_data" jsonb,
 "divorce_data" jsonb
);
alter table public.candidates add primary key(id);
alter table public.documents add primary key(id);
alter table public.personal_files add unique(candidate_id);
